sources = {}

def source(sid, path, date, kind, note):
    p = ROOT / path
    sources[sid] = dict(id=sid, cale=path, hash=hashlib.sha256(p.read_bytes()).hexdigest(), data=date, tip=kind, verificare=note)
    return sid

