def evidence(sid, page='', quote=''):
    s=sources[sid]
    return dict(id=sid, cale=s['cale'], hash=s['hash'], data=s['data'], pagina=page, citat_original=quote)

checklist=[]
def side(offer, contract, status, sid, page='', quote=''):
    return dict(oferta=offer, contract=contract, statut=status, sursa=evidence(sid,page,quote))
def row(theme,b,p,severity='informativ',correction='Nu este necesară o modificare; păstrați distincția dintre ofertă și propunere.'):
    checklist.append(dict(id='C'+str(len(checklist)+1).zfill(2),tema=theme,berger=b,pech=p,severitate=severity,corectie=correction))
def B(o,c,st='AG nou',page='p2–3',q='',sid='B1'): return side(o,c,st,sid,page,q)
