objections=[]
def objection(provider,theme,claim,evaluation,position,ids):
    objections.append(dict(prestator=provider,tema=theme,obiectie_probabila=claim,evaluare=evaluation,pozitie_recomandata=position,sursa=[evidence(i) for i in ids]))
objection('BERGER','Scopul de 13.000 și excavarea','Prețul meu presupunea același concept; calculul excavării era exclus.','Obiecție comercială susținută expres de original, legitimă înaintea acceptării noului pachet. Nu dovedește drept la supliment după o acceptare fără rezerve a noului scop.','Solicitați acceptare completă sau contrapropunere delimitată; nu numiți includerea deja ofertată.',['B1'])
objection('BERGER','12 vizite la 2.000 și tariful 2.000/12','Am oferit maximum 8 vizite, nu 12; nu am oferit 166,67 suplimentar.','Susținut de original. Calculul AG este corect, dar nu tarif primit.','Păstrați statutul AG nou și cereți acord expres; evitați conversia 2.000/8 sau preluarea tarifului PECH.',['B1'])
objection('BERGER','18 luni de la B0, înainte și după','Oferta mea prevedea circa 12 luni pentru serviciile proprii; durata propusă și planificarea înainte sunt mai ample.','Obiecție probabilă și susținută de perioada originală; durata nu este contract acceptat.','Confirmați B0 planificat, calendarul și echipa; prețul 18 luni rămâne propunere, nu constatare.',['B1'])
objection('BERGER','PI extins, ZT §128 și BWB','PI era până la Rohbau plus anexă §128; BWB și alți specialiști nu au fost ofertate.','Parțial/expres susținut de original; prețul nou în același total e negociabil, nu impus retroactiv.','Păstrați delimitarea contribuției originale versus funcțiile noi; cereți nominalizări și costul pachetului complet.',['B1'])
objection('BERGER','Expirarea ofertei','Cele 8 săptămâni au trecut; disponibilitatea și prețul trebuie confirmate.','Susținut de original și de lipsa reconfirmării în jurnal; nu presupuneți o refuzare actuală.','Cereți acceptarea noii propuneri; fără atribuire pe o acceptare pretinsă.',['B1','BJ'])
objection('BERGER','1 milion / polița actuală','Am comunicat 1 milion, acceptat pentru ofertare; nu am acceptat orice limită sau agregat nou.','Susținut de emailuri; nu este dovadă de acoperire PI/BWB/§128 actuală.','Respectați acceptarea pentru ofertare, dar verificați funcțiile, condițiile 6436, agregatul și sublimitele; nu presupuneți 3,5 milioane uniforme.',['BI','BA','BINS'])
objection('BERGER','Etape și PI înainte de execuție','Graficul AG și review-ul PI al planurilor nu erau oferite ca etape separate.','Grafic nou; sumele sunt reconciliate și R05 interzice avansul pentru PI neefectuat.','Negociați livrabilele PI și scadența obiectivă; nu achitați doar pentru planurile elaborate de aceeași persoană fără prestația PI distinctă.',['B1'])
objection('PECH','Bauwerksbuch și funcția PI','AN01 nu numește expres BWB sau asumarea integrală a PI; BWB a fost cerut ulterior separat.','Obiecție susținută de surse, cu nuanța că AN01 trimite la LB AG și cuprinde verificări și contribuții finale. Nu rezultă lipsa oricărei verificări.','Obțineți acord explicit pentru funcțiile complete în 69.300; nu prezentați BWB ca ofertat la zero.',['P1','LB','PB'])
objection('PECH','Index și costuri conexe','AGB păstrează ZT-Index, cheile și costurile întârzierilor.','Condiții originale expres înlocuite de propunere; legitim de negociat înainte de acceptare.','Preț fix pe scop și cheltuieli incluse doar după acord; păstrați efectele legale ale împiedicării distincte.',['P1'])
objection('PECH','Numărul controalelor necesare','Cele 12 pot să nu ajungă; controlul legal nu poate fi omis.','Susținut de realitatea etapizării, nu dovadă că sunt deja necesare toate cele 6 suplimentare. R05 remunerează 13–18 la 450 când sunt reale/neacoperite și aprobate, fără dubla plată.','Confirmați Beschauplan și registrul de numărare; dacă este nevoie peste 18 termene, utilizați procedura de notificare/decizie sigură, nu o limită tehnică automată.',['P1','LB'])
objection('PECH','Teren 800 și recepția comună','Inspecția terenului este o prestație distinctă față de însoțirea execuției.','Pos. 04 și 05 sunt separate în original. Fără bază pentru a elimina automat 800; trebuie însă conținuturi distincte și numărare comună.','Clarificați alocarea celor două livrabile; nu permiteți o nouă taxă de deplasare sau recepție în plus doar pentru faptul că există două funcții în aceeași vizită.',['P1','LB'])
objection('PECH','Formate și drepturi','Drepturile erau păstrate de PECH chiar după plată; toate formatele obligatorii/modelul nativ sunt cerințe mai ample.','Restricția de drepturi este expresă; LB cerea modele la cerere, nu toate livrabilele noi fără discuție.','Confirmați licența pentru proiect, interoperabilitatea și limitele bibliotecilor; nu pretindeți transferul software-ului netransmisibil.',['P1','LB'])
objection('PECH','Plată și retenție','Am oferit 14 zile și Kein Haftrücklass, nu 30 zile și retenție 3 ani.','Obiecție susținută de original. Nu autorizează condiții mai rele decât cele ulterior acceptate.','Negociați mecanismul obiectiv de scadență și alternativa bancară; controlați costurile și evitați dubla securizare.',['P1','LB'])
objection('PECH','Penalitate nouă','Nu am ofertat 0,1%/zi sau plafonul 3.465; BERGER nici nu are penalitate nouă.','Condiție AG nouă vizibilă și negociabilă, nu eroare a ofertei.','Dacă rămâne în propunere, recunoașteți proveniența AG și condițiile limitate; evaluarea juridică este separată.',['P1'])
objection('Ambele','Investigații autonome / laborator / refacere','Un onorariu de proiectare nu este buget total pentru toate investigațiile și probele fizice.','Sursele și §8 separă aceste prestații. BWB complet poate necesita specialiști incluși în pachet, dar nu executarea fizică a tuturor reparațiilor.','Pregătiți lista necesităților/terților cu acord și costuri; păstrați separarea controalelor documentare de teste noi.',['B1','P1','LB'])
objection('Ambele','Împiedicare din sfera AG și durata reală','Un șantier întrerupt sau documente/acces lipsă pot produce timp pierdut și costuri.','R05 păstrează analiza legală și probatorie; nici toate costurile sunt automat excluse, nici toate facturile de staționare sunt automat datorate.','Notificare, cauză, pregătire de executare, costuri și economii documentate; fără tarif lunar fictiv și fără renunțare implicită la drepturi.',['B1','P1'])
objection('Ambele','D1 și celelalte termene noi','Datele relative și disponibilitatea în 24h pot depăși capacitatea noastră.','Nici oferta BERGER, nici PECH nu oferă acel calendar complet; LB conținea alte ipoteze.','Confirmați resursele și calendarul pe livrabile înainte de acceptare; nu afirmați întârzieri contractuale înainte de T0 real.',['B1','P1','LB'])
objection('Ambele','Prețurile originale nu garantează acceptarea extinderilor','Scopul, duratele și garanțiile sunt mai ample chiar dacă totalurile sunt păstrate.','Obiecție comercială plauzibilă. Nu înseamnă că propunerea AG este nelegală sau că o contrapropunere trebuie acceptată.','Tratați R05 ca ofertă completă de negociere. Comparați eventualele contrapropuneri în aceeași matrice de scop/preț și decideți numai după probe.',['B1','P1'])

